def count_frequencies(words):
    """Возвращает словарь: слово -> сколько раз встретилось."""
    result = {}
    for w in words:
        result[w] = result.get(w, 0) + 1
    return result

# Проверяем функцию отдельно, на маленьком примере:
print(count_frequencies(['а', 'б', 'а']))   # {'а': 2, 'б': 1}

